package com.cgsplits;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** What the player brought into the Hunllef room: corrupted armour (helm, body, legs; any tier) and weapons. */
@Getter
@RequiredArgsConstructor
public enum Armour
{
	FULL("T1 Armour", "T1", true),
	NONE("No Armour", "No Arm", true),
	/**
	 * Easter egg: entering with nothing but a basic (tier 1) weapon, or with a partial armour
	 * set. Still counts towards averages; only shown once you've actually done one.
	 */
	BURGER("Burger Enter", "Burger", false),
	/** Older versions saved partial sets as their own type; they load as BURGER. */
	PARTIAL("Partial Armour", "Partial", false);

	private final String displayName;
	/** Short label for the recent runs list. */
	private final String tag;
	/** Always listed in the UI, even with no enters yet. */
	private final boolean alwaysShown;

	/**
	 * @param pieces         armour pieces held (helm, body, legs)
	 * @param bestWeaponTier best weapon tier held: 0 none, 1 basic, 2 attuned, 3 perfected
	 */
	static Armour classify(int pieces, int bestWeaponTier)
	{
		if (pieces >= 3)
		{
			return FULL;
		}
		if (pieces > 0 || bestWeaponTier == 1)
		{
			return BURGER;
		}
		return NONE;
	}
}

package com.cgsplits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Small on-screen box for the current session: EPH and AVG by default, more lines optional. */
class CGSessionOverlay extends OverlayPanel
{
	private final CGSplitsPlugin plugin;
	private final CGSplitsConfig config;

	@Inject
	CGSessionOverlay(CGSplitsPlugin plugin, CGSplitsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Visible inside the instance and in the Prifddinas Gauntlet lobby, hidden elsewhere
		if (!config.showSessionOverlay() || !plugin.isInGauntletArea())
		{
			return null;
		}

		SessionTracker.Snapshot s = plugin.getSession().snapshot(System.currentTimeMillis());
		if (!s.isActive())
		{
			return null;
		}

		// Each line can be switched on or off under Session Overlay; EPH and AVG are on by default
		if (config.sessionShowEph())
		{
			addLine("EPH:", s.getEnters() > 0 ? TimeFormat.eph(s.getEntersPerHour()) : "-", Color.WHITE);
		}
		if (config.sessionShowAvg())
		{
			addLine("AVG:", s.getEnters() > 0 ? TimeFormat.wholeSeconds(s.getAverageEnterTicks()) : "-", Color.WHITE);
		}
		if (config.sessionShowEnters())
		{
			addLine("Enters:", String.valueOf(s.getEnters()), Color.WHITE);
		}
		if (config.sessionShowArmour())
		{
			addLine("T1/No Arm:", s.entersWith(Armour.FULL) + "/" + s.entersWith(Armour.NONE), Color.WHITE);
		}
		if (config.sessionShowResets())
		{
			addLine("Resets:", String.valueOf(s.getResets()), Color.WHITE);
		}
		if (config.sessionShowTime())
		{
			// Red while paused (out of the instance for more than a few ticks)
			addLine("Session:", TimeFormat.duration(s.getElapsedMs()), s.isPaused() ? config.behindColor() : Color.WHITE);
		}

		return super.render(graphics);
	}

	private void addLine(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}
}

package com.cgsplits;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(CGSplitsConfig.GROUP)
public interface CGSplitsConfig extends Config
{
	String GROUP = "cgsplits";

	@ConfigItem(
		keyName = "showTimer",
		name = "Show Timer",
		description = "Show the on-screen Prep / Finish timer while inside the Gauntlet. Runs are still tracked when it's off",
		position = 0
	)
	default boolean showTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "timerPrecision",
		name = "Timer Precision",
		description = "Ticks: the timer updates every game tick (6.0, 6.6, 7.2). Seconds: no decimals (6, 7, 8)",
		position = 1
	)
	default TimerPrecision timerPrecision()
	{
		return TimerPrecision.TICKS;
	}

	@ConfigItem(
		keyName = "showThreeQuarterHpSplit",
		name = "Show 75% HP Split",
		description = "Add a line to the timer with the time from the start of the run until the Hunllef reached 75% HP",
		position = 2
	)
	default boolean showThreeQuarterHpSplit()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showHalfHpSplit",
		name = "Show 50% HP Split",
		description = "Add a line to the timer with the time from the start of the run until the Hunllef reached 50% HP",
		position = 3
	)
	default boolean showHalfHpSplit()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showQuarterHpSplit",
		name = "Show 25% HP Split",
		description = "Add a line to the timer with the time from the start of the run until the Hunllef reached 25% HP",
		position = 4
	)
	default boolean showQuarterHpSplit()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSessionOverlay",
		name = "Show Session Overlay",
		description = "Show a separate on-screen box with this session's stats while in the Gauntlet area; pick its lines under Session Overlay",
		position = 5
	)
	default boolean showSessionOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSidebar",
		name = "Show Sidebar Tab",
		description = "Show the CG Splits tab (last run, stats, session) in the sidebar",
		position = 6
	)
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigSection(
		name = "Session Overlay",
		description = "Which lines the on-screen session box shows",
		position = 7
	)
	String sessionSection = "session";

	@ConfigItem(
		keyName = "sessionShowEph",
		name = "Enters Per Hour",
		description = "Show EPH in the session box",
		position = 8,
		section = sessionSection
	)
	default boolean sessionShowEph()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sessionShowAvg",
		name = "Average Enter",
		description = "Show the average enter time in the session box",
		position = 9,
		section = sessionSection
	)
	default boolean sessionShowAvg()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sessionShowEnters",
		name = "Hunllef Enters",
		description = "Show how many times you've entered the Hunllef room this session",
		position = 10,
		section = sessionSection
	)
	default boolean sessionShowEnters()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sessionShowArmour",
		name = "T1/No Arm",
		description = "Show this session's T1 armour and no armour enters, e.g. 5/12",
		position = 11,
		section = sessionSection
	)
	default boolean sessionShowArmour()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sessionShowResets",
		name = "Resets",
		description = "Show how many runs you reset before the Hunllef this session",
		position = 12,
		section = sessionSection
	)
	default boolean sessionShowResets()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sessionShowTime",
		name = "Session Time",
		description = "Show the session time that EPH is based on",
		position = 13,
		section = sessionSection
	)
	default boolean sessionShowTime()
	{
		return false;
	}

	@ConfigSection(
		name = "Set Threshold",
		description = "What the on-screen timer's colours compare your Preparation, 75%, 50%, 25% and Finish against",
		position = 14
	)
	String paceSection = "pace";

	@ConfigItem(
		keyName = "paceComparison",
		name = "Compare Against",
		description = "Personal: your PB's splits. Custom: the times below. World Record: the current WR",
		position = 15,
		section = paceSection
	)
	default PaceComparison paceComparison()
	{
		return PaceComparison.PERSONAL;
	}

	@ConfigItem(
		keyName = "customPrep",
		name = "Custom Preparation",
		description = "Target preparation time for Custom, e.g. 1:50",
		position = 16,
		section = paceSection
	)
	default String customPrep()
	{
		return "";
	}

	@ConfigItem(
		keyName = "customThreeQuarter",
		name = "Custom 75%",
		description = "Target time from the start of the run until the Hunllef is at 75% HP, for Custom, e.g. 2:25",
		position = 17,
		section = paceSection
	)
	default String customThreeQuarter()
	{
		return "";
	}

	@ConfigItem(
		keyName = "customHalf",
		name = "Custom 50%",
		description = "Target time from the start of the run until the Hunllef is at 50% HP, for Custom, e.g. 3:05",
		position = 18,
		section = paceSection
	)
	default String customHalf()
	{
		return "";
	}

	@ConfigItem(
		keyName = "customQuarter",
		name = "Custom 25%",
		description = "Target time from the start of the run until the Hunllef is at 25% HP, for Custom, e.g. 3:45",
		position = 19,
		section = paceSection
	)
	default String customQuarter()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showGap",
		name = "Show Gap",
		description = "Show how far ahead or behind the target each timer split is, e.g. 4:41.4 (-3.0)",
		position = 20,
		section = paceSection
	)
	default boolean showGap()
	{
		return false;
	}

	@ConfigItem(
		keyName = "aheadColor",
		name = "Ahead Colour",
		description = "Colour for a split that beat the target",
		position = 21,
		section = paceSection
	)
	default Color aheadColor()
	{
		return new Color(0x2ECC40);
	}

	@ConfigItem(
		keyName = "behindColor",
		name = "Behind Colour",
		description = "Colour for a split slower than the target, and for the live timer once it passes the target",
		position = 22,
		section = paceSection
	)
	default Color behindColor()
	{
		return new Color(0xFF4136);
	}

	@ConfigItem(
		keyName = "bestColor",
		name = "Best Colour",
		description = "Personal only: colour for your best ever time at that split",
		position = 23,
		section = paceSection
	)
	default Color bestColor()
	{
		return new Color(0xFFD700);
	}
}

package com.cgsplits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The on-screen timer: Preparation, optionally 75%, 50% and 25%, and Finish, all timed from the start of the
 * run and shown only while inside the instance.
 *
 * Colours compare each split against a target picked in the settings (your PB, your own custom
 * times, or the world record): green once reached under the target, red once over it. A live
 * time turns red as soon as it passes the target, so you see you're behind before the split.
 * With Personal, gold marks your best ever time at that split.
 */
class CGSplitsOverlay extends OverlayPanel
{
	private final CGSplitsPlugin plugin;
	private final CGSplitsConfig config;
	private final RunStore runStore;

	@Inject
	CGSplitsOverlay(CGSplitsPlugin plugin, CGSplitsConfig config, RunStore runStore)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.runStore = runStore;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// The tracker drops the run as soon as the player leaves the instance
		Run run = plugin.getTracker().getCurrent();
		if (run == null || !config.showTimer())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Timer")
			.color(Color.WHITE)
			.build());

		// Preparation: counts up until the Hunllef room, then freezes
		Integer prep = run.getSplits().get(Milestone.BOSS_ROOM);
		addSplit("Preparation:", Milestone.BOSS_ROOM, prep, run.getTicks());

		// 75% / 50% / 25% (each optional): appear once the Hunllef reaches that HP
		addHpSplit(config.showThreeQuarterHpSplit(), "75%:", Milestone.HUNLLEF_75, run);
		addHpSplit(config.showHalfHpSplit(), "50%:", Milestone.HUNLLEF_50, run);
		addHpSplit(config.showQuarterHpSplit(), "25%:", Milestone.HUNLLEF_25, run);

		// Finish: appears once in the boss room, freezes when the kill counts (the game's own
		// time, a few ticks after the Hunllef's HP hits 0)
		if (prep != null)
		{
			addSplit("Finish:", Milestone.HUNLLEF, run.getSplits().get(Milestone.HUNLLEF), run.getTicks());
		}

		return super.render(graphics);
	}

	/** An HP split's line, only when it's turned on and the Hunllef has reached that HP. */
	private void addHpSplit(boolean enabled, String label, Milestone milestone, Run run)
	{
		Integer reached = run.getSplits().get(milestone);
		if (enabled && reached != null)
		{
			addSplit(label, milestone, reached, run.getTicks());
		}
	}

	/**
	 * @param reached the split's tick if reached (frozen), otherwise null and the live tick is shown
	 */
	private void addSplit(String label, Milestone milestone, Integer reached, int live)
	{
		Integer target = target(milestone);
		Color color = Color.WHITE;
		if (reached != null)
		{
			if (target != null)
			{
				color = reached <= target ? config.aheadColor() : config.behindColor();
			}
			if (config.paceComparison() == PaceComparison.PERSONAL)
			{
				Integer best = runStore.bestTick(milestone);
				if (best == null || reached <= best)
				{
					color = config.bestColor();
				}
			}
		}
		else if (target != null && live > target)
		{
			// Still going, but already slower than the target
			color = config.behindColor();
		}

		String time = config.timerPrecision().format(reached != null ? reached : live);
		// Optional gap to the target: once the split is reached, or live once it's already behind
		if (config.showGap() && target != null && (reached != null || live > target))
		{
			time += " (" + TimeFormat.delta((reached != null ? reached : live) - target) + ")";
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(label)
			.right(time)
			.rightColor(color)
			.build());
	}

	/** The target tick for a split, from run start, for the chosen comparison; null if none. */
	private Integer target(Milestone milestone)
	{
		switch (config.paceComparison())
		{
			case CUSTOM:
				switch (milestone)
				{
					case BOSS_ROOM:
						return TimeFormat.parseUserTime(config.customPrep());
					case HUNLLEF_75:
						return TimeFormat.parseUserTime(config.customThreeQuarter());
					case HUNLLEF_50:
						return TimeFormat.parseUserTime(config.customHalf());
					case HUNLLEF_25:
						return TimeFormat.parseUserTime(config.customQuarter());
					default:
						return null;
				}
			case WORLD_RECORD:
				return WorldRecord.ticks(milestone);
			default:
				Run pb = runStore.getPersonalBest();
				return pb != null ? pb.getSplits().get(milestone) : null;
		}
	}
}

package com.cgsplits;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar tab: the last (or selected) run's splits, paceman-style stats across every run
 * including incomplete ones, and a clickable list of recent runs.
 */
class CGSplitsPanel extends PluginPanel
{
	private static final int RECENT_RUNS = 10;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm");
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("MMM d, HH:mm").withZone(ZoneId.systemDefault());
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR.darker();
	private static final Color FAILED = new Color(0xFF8C42);

	private final RunStore runStore;
	private final CGSplitsConfig config;
	private final CGSplitsPlugin plugin;
	private final SessionTracker session;
	private final JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 4));

	// Stats card: Session and Overall share one card with a toggle; built once, updated every second
	private final JPanel statsCard = card(new DynamicGridLayout(0, 1, 0, 2));
	private final JLabel sessionTab;
	private final JLabel overallTab;
	private final JLabel statRuns;
	private final JLabel statEnters;
	private final JLabel statEph;
	private final JLabel statAvgEnter;
	private final JLabel statArmour;
	private final JLabel statBurger;
	private final JLabel statKills;
	private final JLabel statTimeName;
	private final JLabel statTime;
	private final JPanel resetHolder = new JPanel(new CardLayout());
	private final Timer sessionTimer;
	/** Which view of the stats card is showing. */
	private boolean showOverall;
	/** Runs changed while the tab was hidden, so it needs rebuilding when it's next opened. */
	private boolean stale;
	/** Which tab of the splits card is showing; kept when the panel is rebuilt. */
	private String splitsTab = "Main";

	/** Run shown in the detail section; follows the newest run unless the user picked another. */
	private Run selected;
	private long newestSeen;

	@Inject
	CGSplitsPanel(RunStore runStore, CGSplitsConfig config, CGSplitsPlugin plugin)
	{
		this.runStore = runStore;
		this.config = config;
		this.plugin = plugin;
		this.session = plugin.getSession();

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout());
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(content, BorderLayout.NORTH);

		JPanel tabs = new JPanel(new GridLayout(1, 2));
		tabs.setOpaque(false);
		sessionTab = tab("Session", () -> showStats(false));
		overallTab = tab("Overall", () -> showStats(true));
		tabs.add(sessionTab);
		tabs.add(overallTab);
		statsCard.add(tabs);

		statRuns = statRow("Runs")[1];
		statEnters = statRow("Hunllef Enters")[1];
		statEph = statRow("Enters Per Hour")[1];
		statAvgEnter = statRow("Average Enter")[1];
		statArmour = statRow("T1/No Arm")[1];
		statBurger = statRow(Armour.BURGER.getDisplayName())[1];
		statKills = statRow("Kills")[1];
		JLabel[] time = statRow("Session Time");
		statTimeName = time[0];
		statTime = time[1];
		((JPanel) statKills.getParent()).setToolTipText("Hunllef kills, and the share of enters that ended in one");

		// Reset only applies to the session; on Overall its space is kept so the card doesn't jump
		JButton reset = new JButton("Reset Session");
		reset.setFont(FontManager.getRunescapeSmallFont());
		reset.setFocusable(false);
		reset.addActionListener(e ->
		{
			session.reset(System.currentTimeMillis());
			updateStats();
		});
		JPanel noReset = new JPanel();
		noReset.setOpaque(false);
		resetHolder.setOpaque(false);
		resetHolder.add(reset, "session");
		resetHolder.add(noReset, "overall");
		statsCard.add(resetHolder);

		// Only tick while the tab is actually on screen; onActivate catches it up when opened
		sessionTimer = new Timer(1000, e ->
		{
			if (isShowing())
			{
				updateStats();
			}
		});
		sessionTimer.start();

		updateStats();
		refresh();
	}

	void shutDown()
	{
		sessionTimer.stop();
	}

	/**
	 * Runs were loaded or saved. Rebuilding the panel is the most work the plugin does, and a run
	 * is saved right as you leave the instance, so it's put off until the tab is opened.
	 */
	void runsChanged()
	{
		if (isShowing())
		{
			refresh();
		}
		else
		{
			stale = true;
		}
	}

	@Override
	public void onActivate()
	{
		if (stale)
		{
			refresh();
		}
		else
		{
			updateStats();
		}
	}

	private static String hex(Color color)
	{
		return String.format("#%02X%02X%02X", color.getRed(), color.getGreen(), color.getBlue());
	}

	private void showStats(boolean overall)
	{
		showOverall = overall;
		updateStats();
	}

	/**
	 * A clickable tab label for the top of a card; style it with {@link #styleTab}. Switches on
	 * mouse press: Swing drops mouseClicked if the mouse moves even a pixel between press and
	 * release, which made quick clicks miss.
	 */
	private static JLabel tab(String text, Runnable onClick)
	{
		JLabel tab = new JLabel(text, SwingConstants.CENTER);
		tab.setFont(FontManager.getRunescapeSmallFont());
		tab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		tab.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}
		});
		return tab;
	}

	private static void styleTab(JLabel tab, boolean active)
	{
		tab.setForeground(active ? Color.WHITE : MUTED);
		tab.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 2, 0, active ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(2, 0, 3, 0)));
	}

	/** Adds a "name ... value" row to the stats card; returns {name, value}. */
	private JLabel[] statRow(String name)
	{
		JPanel row = row(name, MUTED, "", Color.WHITE, FontManager.getRunescapeSmallFont());
		statsCard.add(row);
		BorderLayout layout = (BorderLayout) row.getLayout();
		return new JLabel[]{
			(JLabel) layout.getLayoutComponent(BorderLayout.WEST),
			(JLabel) layout.getLayoutComponent(BorderLayout.EAST)};
	}

	private void updateStats()
	{
		styleTab(sessionTab, !showOverall);
		styleTab(overallTab, showOverall);
		((CardLayout) resetHolder.getLayout()).show(resetHolder, showOverall ? "overall" : "session");
		if (showOverall)
		{
			showOverallStats();
		}
		else
		{
			showSessionStats();
		}
	}

	private void showSessionStats()
	{
		SessionTracker.Snapshot s = session.snapshot(System.currentTimeMillis());
		statRuns.setText(String.valueOf(s.getRuns()));
		statEnters.setText(String.valueOf(s.getEnters()));
		statEph.setText(s.getEnters() > 0 ? TimeFormat.ephPrecise(s.getEntersPerHour()) : "-");
		((JPanel) statEph.getParent()).setToolTipText("Enters per hour of session time");
		statAvgEnter.setText(s.getEnters() > 0 ? TimeFormat.ticks(s.getAverageEnterTicks()) : "-");
		statArmour.setText(s.entersWith(Armour.FULL) + "/" + s.entersWith(Armour.NONE));
		statKills.setText(kills(s.getKills(), s.getEnters()));

		// The burger row stays hidden until someone actually does one
		SessionTracker.EnterStats burger = s.getByArmour().get(Armour.BURGER);
		statBurger.setText(burger == null ? "-" : TimeFormat.ticks(burger.getAverageTicks()) + " (" + burger.getCount() + ")");
		statBurger.getParent().setVisible(burger != null);

		statTimeName.setText("Session Time");
		((JPanel) statTime.getParent()).setToolTipText("Counts between runs too, but pauses after "
			+ SessionTracker.PAUSE_AFTER_TICKS_OUTSIDE + " ticks outside the instance");
		if (!s.isActive())
		{
			statTime.setText("Not started");
		}
		else if (s.isPaused())
		{
			statTime.setText("<html>" + TimeFormat.duration(s.getElapsedMs())
				+ " <font color='" + hex(config.behindColor()) + "'>(paused)</font></html>");
		}
		else
		{
			statTime.setText(TimeFormat.duration(s.getElapsedMs()));
		}
	}

	/** Every saved run, plus play time counted across all sessions since it was first tracked. */
	private void showOverallStats()
	{
		RunStats stats = runStore.getStats();
		RunStats.MilestoneStats enters = stats.getMilestones().get(Milestone.BOSS_ROOM);
		int enterCount = enters == null ? 0 : enters.getCount();

		statRuns.setText(String.valueOf(stats.getRuns()));
		statEnters.setText(String.valueOf(enterCount));
		statAvgEnter.setText(enterCount > 0 ? TimeFormat.ticks(enters.getAverageTicks()) : "-");
		statArmour.setText(armourEnters(stats, Armour.FULL) + "/" + armourEnters(stats, Armour.NONE));
		statKills.setText(kills(stats.getCompletions(), enterCount));

		RunStats.MilestoneStats burger = stats.getEnters().get(Armour.BURGER);
		statBurger.setText(burger == null ? "-" : TimeFormat.ticks(burger.getAverageTicks()) + " (" + burger.getCount() + ")");
		statBurger.getParent().setVisible(burger != null);

		// EPH only counts enters made while play time was being tracked; older runs have no play time
		PlayTime playTime = session.overall(System.currentTimeMillis());
		double hours = playTime.getMs() / 3_600_000.0;
		statEph.setText(playTime.getEnters() > 0 && hours > 0 ? TimeFormat.ephPrecise(playTime.getEnters() / hours) : "-");
		String since = playTime.getSince() == 0 ? "" : " since " + DATE.format(Instant.ofEpochMilli(playTime.getSince()));
		((JPanel) statEph.getParent()).setToolTipText("Enters per hour of play time" + since);

		statTimeName.setText("Play Time");
		statTime.setText(playTime.getSince() == 0 ? "-" : TimeFormat.duration(playTime.getMs()));
		((JPanel) statTime.getParent()).setToolTipText("All session time" + since + ", including sessions you reset");
	}

	/** "6 (67%)": kills, and the share of enters that ended in one. */
	private static String kills(int kills, int enters)
	{
		return enters > 0 ? kills + " (" + Math.round(100.0 * kills / enters) + "%)" : String.valueOf(kills);
	}

	private static int armourEnters(RunStats stats, Armour armour)
	{
		RunStats.MilestoneStats e = stats.getEnters().get(armour);
		return e == null ? 0 : e.getCount();
	}

	/** Rebuild the panel from the store. Must be called on the Swing EDT. */
	void refresh()
	{
		stale = false;
		List<Run> runs = runStore.getRuns();
		if (runs.isEmpty())
		{
			selected = null;
			newestSeen = 0;
		}
		else
		{
			Run newest = runs.get(0);
			if (selected == null || newest.getStartedAt() > newestSeen)
			{
				selected = newest;
			}
			newestSeen = newest.getStartedAt();
		}

		content.removeAll();

		content.add(header("Top 3"));
		content.add(topThreeCard());

		// Order: Stats (Session/Overall), Splits (Main/Prep/Hunllef), Last Run, Personal Best, Recent Runs
		content.add(header("Stats"));
		content.add(statsCard);
		updateStats();

		content.add(header("Splits"));
		content.add(splitsCard(runStore.getStats()));

		content.add(header(runs.isEmpty() || selected == runs.get(0) ? "Last Run" : "Selected Run"));
		if (selected == null)
		{
			content.add(muted("No runs yet. Enter the Corrupted Gauntlet to start one."));
		}
		else
		{
			content.add(lastRunCard(selected));
		}

		// Your fastest completed run, always here to look back at: a row like Recent Runs,
		// click it to show its splits above
		Run pb = runStore.getPersonalBest();
		if (pb != null)
		{
			content.add(header("Personal Best"));
			content.add(historyRow(pb));
		}

		// Only runs that made it into the Hunllef room; resets would just be noise here
		List<Run> entered = new ArrayList<>();
		for (Run run : runs)
		{
			if (run.hasSplit(Milestone.BOSS_ROOM))
			{
				entered.add(run);
				if (entered.size() == RECENT_RUNS)
				{
					break;
				}
			}
		}
		if (!entered.isEmpty())
		{
			content.add(header("Recent Runs"));
			for (Run run : entered)
			{
				content.add(historyRow(run));
			}
		}

		content.revalidate();
		content.repaint();
	}

	private static final Color[] PODIUM = {new Color(0xFFD700), new Color(0xC0C0C0), new Color(0xCD7F32)};

	/** The fastest three, in gold, silver and bronze; edit {@link WorldRecord#TOP_3} when it changes. */
	private JPanel topThreeCard()
	{
		JPanel card = card(new DynamicGridLayout(0, 1, 0, 3));
		for (int i = 0; i < WorldRecord.TOP_3.length && i < PODIUM.length; i++)
		{
			String name = WorldRecord.TOP_3[i][0];
			String time = WorldRecord.TOP_3[i][1];
			boolean empty = name == null || name.trim().isEmpty();
			// Empty places still show, as "2. -", so the podium is always complete
			if (empty)
			{
				name = "-";
				time = "";
			}
			// "1. rawr simon ... (T1 Prep) 3:57.0": name on the left in bold podium colour; the armour
			// tag sits small, plain and grey just before the time
			String tag = !empty && WorldRecord.TOP_3[i].length > 2 ? WorldRecord.TOP_3[i][2] : "";
			JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
			right.setOpaque(false);
			if (tag != null && !tag.trim().isEmpty())
			{
				JLabel tagLabel = label("(" + tag.trim() + ")", MUTED, FontManager.getRunescapeSmallFont());
				tagLabel.setBorder(new EmptyBorder(0, 0, 0, 6));
				right.add(tagLabel);
			}
			right.add(label(time, PODIUM[i], FontManager.getRunescapeBoldFont()));
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			row.add(label((i + 1) + ". " + name, PODIUM[i], FontManager.getRunescapeBoldFont()), BorderLayout.WEST);
			row.add(right, BorderLayout.EAST);
			// Hover any place for its splits, e.g. "Preparation 1:30.6, Hunllef 2:28.2, Finish 3:58.8"
			String[] entry = WorldRecord.TOP_3[i];
			String prep = entry.length > 3 ? entry[3] : "";
			String fight = entry.length > 4 ? entry[4] : "";
			if (!empty && !prep.isEmpty() && !fight.isEmpty())
			{
				row.setToolTipText("Preparation " + prep + ", Hunllef " + fight + ", Finish " + time);
			}
			card.add(row);
		}
		return card;
	}

	/** Result on the left, that run's splits on the right. */
	private JPanel lastRunCard(Run run)
	{
		JPanel card = card(new BorderLayout(10, 0));
		card.add(runSummary(run), BorderLayout.WEST);
		card.add(splitsTable(run), BorderLayout.CENTER);
		return card;
	}

	private static final String[] GEAR_ROWS = {"Armour", "Staff", "Bow", "Halberd"};

	/**
	 * Stacked so it fits half the panel width: result, time, date, then the armour and each
	 * weapon's tier on entering the Hunllef room. Always the same number of lines, blank where
	 * there's nothing to show, so the card is the same height whichever run is selected.
	 */
	private JPanel runSummary(Run run)
	{
		JPanel summary = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		summary.setOpaque(false);
		summary.add(label(resultText(run), resultColor(run), FontManager.getRunescapeBoldFont()));
		summary.add(label(finalTime(run), Color.WHITE, FontManager.getRunescapeBoldFont()));
		summary.add(label(DATE.format(Instant.ofEpochMilli(run.getStartedAt())), MUTED, FontManager.getRunescapeSmallFont()));

		String[] gear = gearText(run);
		for (int i = 0; i < GEAR_ROWS.length; i++)
		{
			if (gear == null)
			{
				summary.add(label(" ", MUTED, FontManager.getRunescapeSmallFont()));
				continue;
			}
			boolean none = "--".equals(gear[i]);
			JPanel row = row(GEAR_ROWS[i], MUTED, gear[i], none ? MUTED : Color.WHITE, FontManager.getRunescapeSmallFont());
			if (i == 0)
			{
				row.setToolTipText(armourTooltip(run));
			}
			summary.add(row);
		}

		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(summary, BorderLayout.NORTH);
		return top;
	}

	/**
	 * Armour, Staff, Bow and Halberd on entering the Hunllef room: "T1".."T3", or "--" for none.
	 * Null for runs that never entered. Runs saved before every tier was recorded only know the
	 * armour set and which weapons were perfected, so their other weapons show "?".
	 */
	static String[] gearText(Run run)
	{
		if (!run.hasSplit(Milestone.BOSS_ROOM))
		{
			return null;
		}
		Map<String, Integer> gear = run.getGearAtEnter();
		if (gear != null)
		{
			return new String[]{armourText(gear), tierText(gear.get("Staff")), tierText(gear.get("Bow")), tierText(gear.get("Halberd"))};
		}

		Armour armour = run.getArmourAtEnter();
		List<String> perfected = run.getPerfectedAtEnter();
		String[] text = new String[GEAR_ROWS.length];
		text[0] = armour == null ? "?" : armour == Armour.NONE ? "--" : armour.getTag();
		for (int i = 1; i < GEAR_ROWS.length; i++)
		{
			text[i] = perfected != null && perfected.contains(GEAR_ROWS[i]) ? "T3" : "?";
		}
		return text;
	}

	private static final String[] ARMOUR_PIECES = {"Helm", "Body", "Legs"};

	/**
	 * "T1" for a full set of one tier, "T2/T1/T1" (helm/body/legs) for a mixed set, "T1 (2/3)"
	 * for a partial set at its lowest tier, "--" for none.
	 */
	static String armourText(Map<String, Integer> gear)
	{
		int pieces = 0;
		int lowest = Integer.MAX_VALUE;
		int highest = 0;
		for (String piece : ARMOUR_PIECES)
		{
			Integer tier = gear.get(piece);
			if (tier != null)
			{
				pieces++;
				lowest = Math.min(lowest, tier);
				highest = Math.max(highest, tier);
			}
		}
		if (pieces == 0)
		{
			return "--";
		}
		if (pieces < ARMOUR_PIECES.length)
		{
			return "T" + lowest + " (" + pieces + "/3)";
		}
		if (lowest == highest)
		{
			return "T" + lowest;
		}
		return "T" + gear.get("Helm") + "/T" + gear.get("Body") + "/T" + gear.get("Legs");
	}

	private static String tierText(Integer tier)
	{
		return tier == null ? "--" : "T" + tier;
	}

	/** Each armour piece on hover, e.g. "Helm T1, Body T1, Legs --". */
	private static String armourTooltip(Run run)
	{
		Map<String, Integer> gear = run.getGearAtEnter();
		if (gear == null)
		{
			return "Armour on entering the Hunllef room";
		}
		List<String> parts = new ArrayList<>();
		for (String piece : ARMOUR_PIECES)
		{
			parts.add(piece + " " + tierText(gear.get(piece)));
		}
		return String.join(", ", parts);
	}

	/** The splits shown for a single run, always all of them, with "-" for ones it didn't reach. */
	private static final Milestone[] RUN_SPLITS = {
		Milestone.BOSS_ROOM, Milestone.HUNLLEF_75, Milestone.HUNLLEF_50, Milestone.HUNLLEF_25, Milestone.HUNLLEF};
	private static final String[] RUN_SPLIT_NAMES = {"Prep", "75%", "50%", "25%", "End"};
	/** The segment ending at each of {@link #RUN_SPLITS}: the same quarters as the Hunllef tab. */
	private static final Milestone[] RUN_SEGMENTS = {
		null, Milestone.QUARTER_1, Milestone.QUARTER_2, Milestone.QUARTER_3, Milestone.QUARTER_4};

	/**
	 * Prep, the Hunllef's 75/50/25% HP and End, all timed from the start of the run, coloured
	 * against PB/best with the exact gap on hover. Next to each, the time since the split before
	 * it, like the Hunllef tab's quarters but in whole seconds (+46.8 shows as +46), gold when it's
	 * your best ever for that quarter.
	 */
	private JPanel splitsTable(Run run)
	{
		JPanel table = new JPanel(new GridBagLayout());
		table.setOpaque(false);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(table, BorderLayout.NORTH);

		// Compare against your PB, or your previous PB if this run is the PB
		Run pb = runStore.getPersonalBestExcluding(run);
		Map<Milestone, Integer> best = runStore.getBestSplits();

		for (int i = 0; i < RUN_SPLITS.length; i++)
		{
			Milestone milestone = RUN_SPLITS[i];
			JLabel name = cell(RUN_SPLIT_NAMES[i], Color.WHITE, SwingConstants.LEFT);
			Integer tick = run.splitTime(milestone);
			if (tick == null)
			{
				addRow(table, i, name, cell("", MUTED, SwingConstants.RIGHT), cell("-", MUTED, SwingConstants.RIGHT));
				continue;
			}

			Integer pbTick = pb != null ? pb.splitTime(milestone) : null;
			Integer bestTick = best.get(milestone);
			Color color = Color.WHITE;
			if (pbTick != null)
			{
				color = tick <= pbTick ? config.aheadColor() : config.behindColor();
			}
			if (bestTick != null && tick <= bestTick)
			{
				color = config.bestColor();
			}

			JLabel value = cell(TimeFormat.ticks(tick), color, SwingConstants.RIGHT);
			if (pbTick != null)
			{
				value.setToolTipText(TimeFormat.delta(tick - pbTick) + " vs PB");
			}
			addRow(table, i, name, segmentCell(run, RUN_SEGMENTS[i], best), value);
		}
		return top;
	}

	/** "+46": time since the split before, in whole seconds; blank for Prep or a missing split. */
	private JLabel segmentCell(Run run, Milestone segment, Map<Milestone, Integer> best)
	{
		Integer ticks = segment == null ? null : run.splitTime(segment);
		JLabel cell = cell(ticks == null ? "" : "+" + TimeFormat.wholeSeconds(ticks), Color.WHITE, SwingConstants.RIGHT);
		if (ticks != null)
		{
			Integer bestTicks = best.get(segment);
			if (bestTicks != null && ticks <= bestTicks)
			{
				cell.setForeground(config.bestColor());
			}
			cell.setToolTipText(segment.getDisplayName() + "% HP: +" + TimeFormat.ticks(ticks));
		}
		return cell;
	}

	/** Segments are shown as "+40.8" to read as time added after the split before them. */
	private static String formatSplit(Milestone milestone, int ticks)
	{
		return milestone.isRelative() ? "+" + TimeFormat.ticks(ticks) : TimeFormat.ticks(ticks);
	}

	/** Split name, indented for the HP quarters under the Hunllef fight. */
	private static JLabel splitName(Milestone milestone)
	{
		JLabel name = cell(milestone.getDisplayName(), milestone.isSubSplit() ? MUTED : Color.WHITE, SwingConstants.LEFT);
		if (milestone.isSubSplit())
		{
			name.setBorder(new EmptyBorder(0, 10, 0, 0));
			name.setToolTipText("Time to take the Hunllef from " + milestone.getDisplayName().replace("-", "% to ") + "% HP");
		}
		else if (milestone == Milestone.HUNLLEF_FIGHT)
		{
			name.setToolTipText("The whole fight, from entering the room to the kill");
		}
		return name;
	}

	private static JLabel label(String text, Color color, Font font)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	private static final String[] SPLIT_TABS = {"Main", "Prep", "Hunllef"};

	/**
	 * Every split's count, average and best in one card, a tab per group: Main (the Timer's
	 * splits), Prep (milestones and enters by armour) and Hunllef (the fight and its quarters).
	 * A CardLayout sizes the card to the tallest tab, so switching doesn't move what's below.
	 */
	private JPanel splitsCard(RunStats stats)
	{
		JPanel card = card(new BorderLayout(0, 6));
		CardLayout cards = new CardLayout();
		JPanel pages = new JPanel(cards);
		pages.setOpaque(false);
		pages.add(topAligned(splitsTable(Milestone.MAIN, stats)), SPLIT_TABS[0]);
		JPanel prep = splitsTable(Milestone.PREP, stats);
		addEnterRows(prep, Milestone.PREP.size() + 1, stats);
		pages.add(topAligned(prep), SPLIT_TABS[1]);
		pages.add(topAligned(splitsTable(Milestone.FIGHT, stats)), SPLIT_TABS[2]);

		JPanel tabs = new JPanel(new GridLayout(1, SPLIT_TABS.length));
		tabs.setOpaque(false);
		JLabel[] labels = new JLabel[SPLIT_TABS.length];
		for (int i = 0; i < SPLIT_TABS.length; i++)
		{
			String name = SPLIT_TABS[i];
			labels[i] = tab(name, () ->
			{
				splitsTab = name;
				cards.show(pages, name);
				for (JLabel l : labels)
				{
					styleTab(l, l.getText().equals(name));
				}
			});
			styleTab(labels[i], name.equals(splitsTab));
			tabs.add(labels[i]);
		}
		cards.show(pages, splitsTab);

		card.add(tabs, BorderLayout.NORTH);
		card.add(pages, BorderLayout.CENTER);
		return card;
	}

	private JPanel splitsTable(List<Milestone> milestones, RunStats stats)
	{
		JPanel table = new JPanel(new GridBagLayout());
		table.setOpaque(false);
		addRow(table, 0, headerCells("Split"));
		addMilestoneRows(table, 1, milestones, stats);
		return table;
	}

	private static JPanel topAligned(JPanel panel)
	{
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(panel, BorderLayout.NORTH);
		return top;
	}

	/** Enters by armour: how many, average and best enter time, and kill rate on hover. */
	private void addEnterRows(JPanel table, int row, RunStats stats)
	{

		for (Armour armour : Armour.values())
		{
			// Burger enters only get a row once you've done one; old partial runs load as burgers
			if (armour == Armour.PARTIAL || (!armour.isAlwaysShown() && !stats.getEnters().containsKey(armour)))
			{
				continue;
			}
			RunStats.MilestoneStats e = stats.getEnters().get(armour);
			JLabel count = cell(e != null ? String.valueOf(e.getCount()) : "0", Color.WHITE, SwingConstants.RIGHT);
			int killRate = stats.completionPercent(armour);
			if (killRate >= 0)
			{
				count.setToolTipText(killRate + "% of these enters ended in a kill");
			}
			JLabel name = cell(armour.getDisplayName() + " Enter", Color.WHITE, SwingConstants.LEFT);
			name.setToolTipText("Preparation times of runs that entered with " + armour.getDisplayName());
			addRow(table, row++,
				name,
				count,
				cell(e != null ? TimeFormat.ticks(e.getAverageTicks()) : "-", Color.WHITE, SwingConstants.RIGHT),
				cell(e != null ? TimeFormat.ticks(e.getBestTicks()) : "-", config.bestColor(), SwingConstants.RIGHT));
		}
	}

	/** paceman-style rows: how many runs reached each split, and the average/best time. */
	private int addMilestoneRows(JPanel table, int row, List<Milestone> milestones, RunStats stats)
	{
		for (Milestone milestone : milestones)
		{
			RunStats.MilestoneStats m = stats.getMilestones().get(milestone);
			JLabel count = cell(m != null ? String.valueOf(m.getCount()) : "0", Color.WHITE, SwingConstants.RIGHT);
			count.setToolTipText(stats.percentReached(milestone) + "% of runs reached this split");
			addRow(table, row++,
				splitName(milestone),
				count,
				cell(m != null ? formatSplit(milestone, m.getAverageTicks()) : "-", Color.WHITE, SwingConstants.RIGHT),
				cell(m != null ? formatSplit(milestone, m.getBestTicks()) : "-", config.bestColor(), SwingConstants.RIGHT));
		}
		return row;
	}

	private static JLabel[] headerCells(String first)
	{
		return new JLabel[]{
			cell(first, MUTED, SwingConstants.LEFT),
			cell("Count", MUTED, SwingConstants.RIGHT),
			cell("Avg", MUTED, SwingConstants.RIGHT),
			cell("Best", MUTED, SwingConstants.RIGHT),
		};
	}

	/**
	 * Adds a table row where the first (name) column takes all spare width and the number
	 * columns are only as wide as their contents, so names like "1st weapon" aren't cut off.
	 */
	private static void addRow(JPanel table, int row, JLabel... cells)
	{
		for (int col = 0; col < cells.length; col++)
		{
			GridBagConstraints c = new GridBagConstraints();
			c.gridx = col;
			c.gridy = row;
			c.weightx = col == 0 ? 1 : 0;
			c.fill = GridBagConstraints.HORIZONTAL;
			c.anchor = col == 0 ? GridBagConstraints.WEST : GridBagConstraints.EAST;
			c.insets = new Insets(1, col == 0 ? 0 : 8, 1, 0);
			table.add(cells[col], c);
		}
	}

	private JPanel historyRow(Run run)
	{
		Color background = run == selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR;
		// e.g. "2:18.6  T1" on the left, the finish time (or Died / Left) on the right
		String enter = TimeFormat.ticks(run.getSplits().get(Milestone.BOSS_ROOM));
		Armour armour = run.getArmourAtEnter();
		JPanel line = row(armour != null ? enter + "  " + armour.getTag() : enter, Color.WHITE,
			run.isCompleted() ? finalTime(run) : resultText(run), resultColor(run),
			FontManager.getRunescapeSmallFont());
		// When it happened underneath, e.g. "Today 14:32", so the order is easy to follow
		JPanel row = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
		row.add(line);
		row.add(label(when(run.getStartedAt()), MUTED, FontManager.getRunescapeSmallFont()));
		row.setBackground(background);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText("Show this run's splits. Right-click to delete it.");

		// Right-click > Delete Run, e.g. for a test kill that shouldn't count towards averages
		JPopupMenu menu = new JPopupMenu();
		JMenuItem delete = new JMenuItem("Delete Run");
		delete.addActionListener(e -> confirmDelete(run));
		menu.add(delete);
		row.setComponentPopupMenu(menu);
		inheritPopupMenu(row);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// On press, like the tabs, so a click with a little mouse movement still counts
				if (SwingUtilities.isLeftMouseButton(e))
				{
					selected = run;
					refresh();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(background);
			}
		});
		return row;
	}

	/** Lets right-clicks anywhere on a row, including its labels, open the row's menu. */
	private static void inheritPopupMenu(Container container)
	{
		for (Component child : container.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof Container)
			{
				inheritPopupMenu((Container) child);
			}
		}
	}

	/** Asks first, since a deleted run can't be brought back. */
	private void confirmDelete(Run run)
	{
		String what = run.isCompleted() ? "finished in " + finalTime(run) : resultText(run).toLowerCase();
		int choice = JOptionPane.showConfirmDialog(this,
			"<html>Delete this run (" + when(run.getStartedAt()) + ", " + what + ")?<br>"
				+ "It's removed from your PB, splits and averages for good.</html>",
			"Delete Run", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}
		if (selected == run)
		{
			selected = null; // show the newest run instead
		}
		plugin.deleteRun(run);
		updateStats();
	}

	private static String resultText(Run run)
	{
		// Runs that got into the boss room ended at the Hunllef: "Died at Hunllef", "Reset at Hunllef"
		String where = run.hasSplit(Milestone.BOSS_ROOM) ? " at Hunllef" : "";
		switch (run.resolveEndReason())
		{
			case COMPLETED:
				return "Completed";
			case DIED:
				return "Died" + where;
			case ABANDONED:
				return "Abandoned" + where;
			default:
				return "Reset" + where;
		}
	}

	private static Color resultColor(Run run)
	{
		switch (run.resolveEndReason())
		{
			case COMPLETED:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case DIED:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			default:
				return FAILED;
		}
	}

	private static String finalTime(Run run)
	{
		// Ticks are already snapped to the game's official time, so this matches it
		return TimeFormat.ticks(run.getTicks());
	}

	private static JLabel header(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(new EmptyBorder(8, 0, 2, 0));
		return label;
	}

	private static JLabel muted(String text)
	{
		JLabel label = new JLabel("<html>" + text + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED);
		return label;
	}

	private static JPanel card(java.awt.LayoutManager layout)
	{
		JPanel card = new JPanel(layout);
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(6, 6, 6, 6));
		return card;
	}

	private static JPanel row(String left, Color leftColor, String right, Color rightColor, Font font)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JLabel l = new JLabel(left);
		l.setFont(font);
		l.setForeground(leftColor);
		JLabel r = new JLabel(right);
		r.setFont(font);
		r.setForeground(rightColor);
		row.add(l, BorderLayout.WEST);
		row.add(r, BorderLayout.EAST);
		return row;
	}

	/** "Today 14:32", "Yesterday 09:05", or "Nov 12, 21:40" for older runs. */
	private static String when(long epochMs)
	{
		ZonedDateTime time = Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault());
		LocalDate today = LocalDate.now(ZoneId.systemDefault());
		if (time.toLocalDate().equals(today))
		{
			return "Today " + CLOCK.format(time);
		}
		if (time.toLocalDate().equals(today.minusDays(1)))
		{
			return "Yesterday " + CLOCK.format(time);
		}
		return DATE.format(time);
	}

	private static JLabel cell(String text, Color color, int alignment)
	{
		JLabel label = new JLabel(text, alignment);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}
}

package com.cgsplits;

import com.google.inject.Injector;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "CG Splits",
	description = "LiveSplit-style auto-splits and personal bests for the Corrupted Gauntlet",
	tags = {"gauntlet", "corrupted", "cg", "hunllef", "splits", "timer", "speedrun", "pb"},
	internalName = "cg-splits",
	legacyDataDirectory = "cg-splits"
)
public class CGSplitsPlugin extends Plugin
{
	// TODO verify these IDs in a dev client (Varbit inspector / region debug overlay).
	static final int VARBIT_GAUNTLET_FINAL_ROOM_ENTERED = 9177;
	static final int VARBIT_GAUNTLET_ENTERED = 9178;
	static final int REGION_GAUNTLET = 7512;
	static final int REGION_CORRUPTED_GAUNTLET = 7768;
	/** The Gauntlet lobby building in Prifddinas. */
	static final int REGION_GAUNTLET_LOBBY = 12127;

	private static final int INVENTORY = 93;
	private static final int EQUIPMENT = 94;

	private static final Pattern DURATION = Pattern.compile("challenge duration: (\\d+:\\d{2}(?:\\.\\d+)?)", Pattern.CASE_INSENSITIVE);
	private static final Pattern PREP = Pattern.compile("preparation time: (\\d+:\\d{2}(?:\\.\\d+)?)", Pattern.CASE_INSENSITIVE);

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CGSplitsOverlay overlay;

	@Inject
	private CGSessionOverlay sessionOverlay;

	@Inject
	private CGSplitsConfig config;

	@Inject
	private RunStore runStore;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Injector injector;

	@Getter
	private final RunTracker tracker = new RunTracker(RunTracker.GAME_TIMER_START_DELAY);

	@Getter
	private final SessionTracker session = new SessionTracker();

	/** Inside a Gauntlet instance or the Prifddinas Gauntlet lobby. */
	@Getter
	private volatile boolean inGauntletArea;

	/** False while the current run is on a Leagues, Deadman or other special world. */
	private boolean countThisRun = true;

	private CGSplitsPanel panel;
	private NavigationButton navButton;
	private Runnable storeListener;

	@Provides
	CGSplitsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CGSplitsConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		panel = injector.getInstance(CGSplitsPanel.class);
		storeListener = () -> SwingUtilities.invokeLater(panel::runsChanged);
		runStore.addListener(storeListener);
		// RuneLite gives each plugin its own data folder (.runelite/plugin-data/cg-splits) and
		// moves our old .runelite/cg-splits folder into it the first time
		runStore.load(getPluginDirectory());
		session.setOverall(runStore.loadPlayTime());

		navButton = NavigationButton.builder()
			.tooltip("CG Splits")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		updateSidebar();
		overlayManager.add(overlay);
		overlayManager.add(sessionOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(sessionOverlay);
		clientToolbar.removeNavigation(navButton);

		// Keep the run in progress in the stats instead of silently dropping it
		Run unfinished = tracker.abandon();
		if (unfinished != null && unfinished.getTicks() > 0 && countThisRun)
		{
			onRunEnded(unfinished);
		}
		session.pause(System.currentTimeMillis());
		savePlayTime();

		runStore.removeListener(storeListener);
		panel.shutDown();
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		boolean inGauntlet = client.getVarbitValue(VARBIT_GAUNTLET_ENTERED) == 1;
		boolean inBossRoom = client.getVarbitValue(VARBIT_GAUNTLET_FINAL_ROOM_ENTERED) == 1;

		long now = System.currentTimeMillis();
		RunTracker.State before = tracker.getState();
		Run ended = tracker.onTick(inGauntlet, client.getTopLevelWorldView().isInstance(), inBossRoom, regionMode(), now);
		RunTracker.State after = tracker.getState();

		if (after == RunTracker.State.BOSS)
		{
			readHunllefHealth();
		}
		else if (before == RunTracker.State.FINISHED)
		{
			// The ticks between the kill and leaving, to check the timer against the game's
			Run run = after == RunTracker.State.FINISHED ? tracker.getCurrent() : ended;
			log.debug("CG after kill: state={} timer={} finish={} inGauntlet={} instance={}",
				after, run == null ? null : run.getTicks(), run == null ? null : run.getSplits().get(Milestone.HUNLLEF),
				inGauntlet, client.getTopLevelWorldView().isInstance());
		}

		if (before == RunTracker.State.IDLE && after == RunTracker.State.PREP)
		{
			// Leagues, Deadman and other special worlds play differently, so their runs are
			// timed on screen but kept out of PBs, splits and the session
			countThisRun = isStandardWorld();
			if (countThisRun)
			{
				session.onRunStarted(now);
			}
			else
			{
				log.debug("Gauntlet run on a special world ({}): not counting it", client.getWorldType());
			}
		}
		else if (before == RunTracker.State.PREP && after == RunTracker.State.BOSS)
		{
			Run run = tracker.getCurrent();
			if (countThisRun && run.isCorrupted() && !run.isWeaponlessEnter())
			{
				session.onEnter(run.getSplits().get(Milestone.BOSS_ROOM), run.getArmourAtEnter());
				if (run.getArmourAtEnter() == Armour.BURGER)
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ff9040>Burger Enter.</col>", null);
				}
			}
		}

		if (ended != null)
		{
			if (countThisRun)
			{
				boolean counted = ended.isCorrupted() && !ended.isWeaponlessEnter();
				session.onRunEnded(counted && ended.isReset(), counted && ended.isCompleted());
				onRunEnded(ended);
				savePlayTime();
			}
			else
			{
				log.debug("Not saving Gauntlet run from a special world");
			}
		}

		// Session clock keeps running between runs, but pauses after a few ticks outside the instance (AFK).
		// Runs on special worlds don't count, so neither does their time.
		session.onTick(inGauntlet && countThisRun, now);
		inGauntletArea = inGauntlet || worldRegion() == REGION_GAUNTLET_LOBBY;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			session.pause(System.currentTimeMillis());
			savePlayTime();
			inGauntletArea = false;
		}
	}

	/** Saves the overall play time, so it carries over to the next time the client starts. */
	private void savePlayTime()
	{
		runStore.savePlayTime(session.overall(System.currentTimeMillis()));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CGSplitsConfig.GROUP.equals(event.getGroup()) && "showSidebar".equals(event.getKey()))
		{
			updateSidebar();
		}
	}

	private void updateSidebar()
	{
		if (config.showSidebar())
		{
			clientToolbar.addNavigation(navButton);
		}
		else
		{
			clientToolbar.removeNavigation(navButton);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() instanceof NPC)
		{
			if (tracker.isRunning())
			{
				log.debug("CG NPC died: {}", event.getActor().getName());
			}
			tracker.onNpcDeath(event.getActor().getName());
		}
		else if (event.getActor() == client.getLocalPlayer())
		{
			tracker.onLocalPlayerDeath();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if ((id != INVENTORY && id != EQUIPMENT) || !tracker.isRunning())
		{
			return;
		}

		List<String> names = new ArrayList<>();
		addItemNames(client.getItemContainer(INVENTORY), names);
		addItemNames(client.getItemContainer(EQUIPMENT), names);
		tracker.onItems(names);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		Matcher duration = DURATION.matcher(message);
		Matcher prep = PREP.matcher(message);
		tracker.onOfficialTimes(
			duration.find() ? duration.group(1) : null,
			prep.find() ? prep.group(1) : null);
	}

	/**
	 * Deletes a saved run for good (e.g. a test kill), and takes it back out of the session and
	 * overall totals so it doesn't skew the averages.
	 */
	void deleteRun(Run run)
	{
		// Only once: a double-click on Delete mustn't take the run out of the totals twice
		if (!runStore.delete(run))
		{
			return;
		}
		log.debug("Deleted Gauntlet run from {}: ticks={} splits={}", run.getStartedAt(), run.getTicks(), run.getSplits());
		session.removeRun(run);
		savePlayTime();
	}

	private void onRunEnded(Run run)
	{
		if (!run.isCorrupted())
		{
			return;
		}
		if (run.isWeaponlessEnter())
		{
			log.debug("Not saving Gauntlet run: entered the Hunllef room without a weapon");
			return;
		}

		log.debug("Gauntlet run ended: completed={} ticks={} splits={}", run.isCompleted(), run.getTicks(), run.getSplits());
		log.debug("CG timer sync: arrival delay {} ticks, prep drift {} ticks, finish drift {} ticks (positive = our timer was ahead of the game's)",
			tracker.getArrivalDelayTicks(), run.getPrepDriftTicks(), run.getTimerDriftTicks());
		runStore.save(run);
	}

	private void addItemNames(ItemContainer container, List<String> names)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				names.add(itemManager.getItemComposition(item.getId()).getName());
			}
		}
	}

	/** A small red hourglass with gold sand, drawn in code so the plugin needs no image resources. */
	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Top and bottom caps
		g.setColor(new Color(0x8E2A20));
		g.fillRect(2, 0, 12, 2);
		g.fillRect(2, 14, 12, 2);

		// Glass: two triangles meeting in the middle
		Path2D glass = new Path2D.Double();
		glass.moveTo(3, 2);
		glass.lineTo(13, 2);
		glass.lineTo(8, 8);
		glass.lineTo(13, 14);
		glass.lineTo(3, 14);
		glass.lineTo(8, 8);
		glass.closePath();
		g.setColor(new Color(0xC0392B));
		g.fill(glass);

		// Sand piled in the bottom
		Path2D sand = new Path2D.Double();
		sand.moveTo(5.5, 13);
		sand.lineTo(10.5, 13);
		sand.lineTo(8, 10);
		sand.closePath();
		g.setColor(new Color(0xF1C40F));
		g.fill(sand);

		g.dispose();
		return image;
	}

	/**
	 * Feeds the Hunllef's HP to the tracker: exact from the boss HP HUD when it matches the
	 * health bar, else the bar's upper bound. Only known once the Hunllef has been hit (ratio -1
	 * before that), which is fine for the 75/50/25% thresholds.
	 */
	private void readHunllefHealth()
	{
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			String name = npc.getName();
			if (name == null || !name.toLowerCase().contains("hunllef"))
			{
				continue;
			}
			double fraction = RunTracker.bossHealthFraction(
				npc.getHealthRatio(),
				npc.getHealthScale(),
				client.getVarbitValue(VarbitID.HPBAR_HUD_HP),
				client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP));
			if (fraction >= 0)
			{
				tracker.onBossHealth(fraction);
			}
			return;
		}
	}

	/** World types whose Gauntlet runs don't count: different rules, relics, or temporary characters. */
	private static final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(
		WorldType.SEASONAL,           // Leagues
		WorldType.DEADMAN,
		WorldType.FRESH_START_WORLD,
		WorldType.BETA_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.NOSAVE_MODE,
		WorldType.PVP_ARENA,
		WorldType.LAST_MAN_STANDING);

	/** A normal (members) world, where runs count towards stats. */
	private boolean isStandardWorld()
	{
		for (WorldType type : client.getWorldType())
		{
			if (SPECIAL_WORLDS.contains(type))
			{
				return false;
			}
		}
		return true;
	}

	/** Region of the player's real (non-instance) location, or -1. */
	private int worldRegion()
	{
		Player player = client.getLocalPlayer();
		return player != null ? player.getWorldLocation().getRegionID() : -1;
	}

	private Run.Mode regionMode()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return Run.Mode.UNKNOWN;
		}

		LocalPoint local = player.getLocalLocation();
		WorldPoint point = WorldPoint.fromLocalInstance(client, local);
		if (point == null)
		{
			return Run.Mode.UNKNOWN;
		}

		switch (point.getRegionID())
		{
			case REGION_CORRUPTED_GAUNTLET:
				return Run.Mode.CORRUPTED;
			case REGION_GAUNTLET:
				return Run.Mode.NORMAL;
			default:
				return Run.Mode.UNKNOWN;
		}
	}
}

package com.cgsplits;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A split point inside a Gauntlet run. Splits are milestone-based (like paceman.gg),
 * not order-based: prep routes differ, so each milestone is recorded the first time
 * it happens and compared against the tick the PB run reached the same milestone.
 *
 * Recorded splits are stored as ticks since the run started. Some milestones are segments
 * measured between two recorded splits (e.g. the Hunllef fight, from Enter to Finish); see
 * {@link #end()}, {@link #since()} and {@link Run#splitTime(Milestone)}.
 */
@Getter
@RequiredArgsConstructor
public enum Milestone
{
	FIRST_WEAPON("1st Weapon", true, false),
	/** First demi-boss (bear, dragon or dark beast) killed. */
	DEMIS("Demi Killed", true, false),
	FIRST_PERFECTED("Perfected Weapon", true, false),
	SECOND_PERFECTED("2nd Perfected", true, false),
	/** Entered the Hunllef room. */
	BOSS_ROOM("Preparation", true, false),

	/** The whole fight, Enter to Finish. */
	HUNLLEF_FIGHT("Hunllef", true, false),
	/** Each quarter of the Hunllef's HP on its own, to see where damage dropped off. */
	QUARTER_1("100-75", true, true),
	QUARTER_2("75-50", true, true),
	QUARTER_3("50-25", true, true),
	QUARTER_4("25-0", true, true),

	/** The Hunllef died: the run's total time. */
	HUNLLEF("Finish", true, false),

	/**
	 * Recorded HP thresholds that the quarters are built from, each also shown as a Main split
	 * ("75%", "50%", "25%") timed from the start of the run like on the Timer.
	 */
	HUNLLEF_75("75%", true, false),
	HUNLLEF_50("50%", true, false),
	HUNLLEF_25("25%", true, false),

	// Older versions split on each demi-boss. Kept only so those run files still load;
	// RunStore folds them into DEMIS.
	BEAR("Bear", false, false),
	DRAGON("Dragon", false, false),
	DARK_BEAST("Dark Beast", false, false),
	/** Older versions split on completing T1 armour; the T1 Enter row covers it now. Dropped on load. */
	FULL_ARMOUR("T1 Armour", false, false);

	private final String displayName;
	private final boolean shown;
	/** Listed indented under the Hunllef fight. */
	private final boolean subSplit;

	/** Preparation, the Hunllef's 75/50/25% HP and Finish, listed under the "Main" tab. */
	public static final List<Milestone> MAIN = Collections.unmodifiableList(Arrays.asList(
		BOSS_ROOM, HUNLLEF_75, HUNLLEF_50, HUNLLEF_25, HUNLLEF));

	/** Prep milestones, listed under the "Prep" tab of the sidebar's splits card. */
	public static final List<Milestone> PREP = Collections.unmodifiableList(Arrays.asList(
		FIRST_WEAPON, DEMIS, FIRST_PERFECTED, SECOND_PERFECTED));

	/** The Hunllef fight and its HP quarters, listed under the "Hunllef" tab. */
	public static final List<Milestone> FIGHT = Collections.unmodifiableList(Arrays.asList(
		HUNLLEF_FIGHT, QUARTER_1, QUARTER_2, QUARTER_3, QUARTER_4));

	/** Recorded HP thresholds: stored from the run start, moved with Enter when it's corrected. */
	static final List<Milestone> HP_THRESHOLDS = Collections.unmodifiableList(Arrays.asList(
		HUNLLEF_75, HUNLLEF_50, HUNLLEF_25));

	/** The recorded split this milestone ends at (itself, unless it's a segment). */
	public Milestone end()
	{
		switch (this)
		{
			case HUNLLEF_FIGHT:
			case QUARTER_4:
				return HUNLLEF;
			case QUARTER_1:
				return HUNLLEF_75;
			case QUARTER_2:
				return HUNLLEF_50;
			case QUARTER_3:
				return HUNLLEF_25;
			default:
				return this;
		}
	}

	/** The recorded split this milestone is timed from, or null for the start of the run. */
	public Milestone since()
	{
		switch (this)
		{
			case HUNLLEF_FIGHT:
			case QUARTER_1:
				return BOSS_ROOM;
			case QUARTER_2:
				return HUNLLEF_75;
			case QUARTER_3:
				return HUNLLEF_50;
			case QUARTER_4:
				return HUNLLEF_25;
			default:
				return null;
		}
	}

	/** Timed from another split rather than the run start; shown with a "+". */
	public boolean isRelative()
	{
		return since() != null;
	}

	/** Computed from other splits rather than recorded directly. */
	public boolean isSegment()
	{
		return end() != this;
	}
}

