		assertTrue(tracker.getCurrent().hasSplit(Milestone.HUNLLEF_50));
		assertFalse(tracker.getCurrent().hasSplit(Milestone.HUNLLEF_25));
	}

	@Test
	public void bossHealthFromBarAndHud()
	{
		// Bar of 30 with 1000 max HP: ratio 15 covers 483-516 HP
		assertEquals(0.509, RunTracker.bossHealthFraction(15, 30, 509, 1000), 1e-9);
		assertEquals(0.499, RunTracker.bossHealthFraction(15, 30, 499, 1000), 1e-9);
		// HUD off or stale (doesn't match the bar): highest HP the bar allows, never below 50%
		double bar15 = RunTracker.bossHealthFraction(15, 30, 0, 0);
		assertTrue(bar15 >= 0.5 && bar15 < 15 / 29.0);
		assertEquals(bar15, RunTracker.bossHealthFraction(15, 30, 200, 1000), 0);
		assertTrue(RunTracker.bossHealthFraction(14, 30, 0, 0) < 0.5);
		// Unknown before the first hit, 0 once dead, never above full
		assertEquals(-1, RunTracker.bossHealthFraction(-1, -1, 509, 1000), 0);
		assertEquals(0, RunTracker.bossHealthFraction(0, 30, 0, 1000), 0);
		assertTrue(RunTracker.bossHealthFraction(30, 30, 0, 0) <= 1);
	}

	@Test
	public void hunllefHpThresholdsTimedFromEntry()
	{
		tick(true, false);
		ticks(100);
		tracker.onBossHealth(0.5); // ignored during prep
		assertFalse(tracker.getCurrent().hasSplit(Milestone.HUNLLEF_50));

		tick(true, true); // enter at tick 101
		ticks(20);
		tracker.onBossHealth(0.80);
		ticks(10);
		tracker.onBossHealth(0.74); // tick 131: 30 ticks after entry
		ticks(30);
		tracker.onBossHealth(0.20); // one big drop passes both 50% and 25%

		Run run = tracker.getCurrent();
		assertEquals(Integer.valueOf(30), run.splitTime(Milestone.QUARTER_1)); // 100-75
		assertEquals(Integer.valueOf(30), run.splitTime(Milestone.QUARTER_2)); // 75-50
		assertEquals(Integer.valueOf(0), run.splitTime(Milestone.QUARTER_3));  // 50-25, same hit
		// 50% is a full-run time, like Preparation and Finish
		assertEquals(Integer.valueOf(161), run.splitTime(Milestone.HUNLLEF_50));

		tracker.onBossHealth(0.10); // later readings don't move a split
		assertEquals(Integer.valueOf(0), run.splitTime(Milestone.QUARTER_3));

		// Official prep 1 tick earlier than ours: the whole fight moves with Enter, so the
		// quarters keep their lengths and 50% moves 1 tick earlier too
		tracker.onNpcDeath("Corrupted Hunllef");
		tracker.onOfficialTimes(null, "1:00.00"); // 100 ticks
		assertEquals(Integer.valueOf(100), run.getSplits().get(Milestone.BOSS_ROOM));
		assertEquals(Integer.valueOf(30), run.splitTime(Milestone.QUARTER_1));
		assertEquals(Integer.valueOf(30), run.splitTime(Milestone.QUARTER_2));
		assertEquals(Integer.valueOf(160), run.splitTime(Milestone.HUNLLEF_50));
	}

	@Test
	public void burgerEnters()
	{
		// Basic weapon and nothing else
		assertEquals(Armour.BURGER, Armour.classify(0, 1));
		// Partial armour, whatever the weapon
		assertEquals(Armour.BURGER, Armour.classify(1, 3));
		assertEquals(Armour.BURGER, Armour.classify(2, 1));
		// Real enters
		assertEquals(Armour.NONE, Armour.classify(0, 2));
		assertEquals(Armour.NONE, Armour.classify(0, 3));
		assertEquals(Armour.FULL, Armour.classify(3, 1));

		// Through the tracker: basic staff only
		tick(true, false);
		ticks(10);
		tracker.onItems(Collections.singletonList("Corrupted staff (basic)"));
		tick(true, true);
		assertEquals(Armour.BURGER, tracker.getCurrent().getArmourAtEnter());
		tick(false, false);

		// Upgrading a basic weapon to attuned is no longer a burger
		tick(true, false);
		tracker.onItems(Collections.singletonList("Corrupted bow (basic)"));
		ticks(10);
		tracker.onItems(Collections.singletonList("Corrupted bow (attuned)"));
		tick(true, true);
		assertEquals(Armour.NONE, tracker.getCurrent().getArmourAtEnter());

		// Old saved partial-armour enters load as burgers
		Run old = new Run();
		old.setArmourAtEnter(Armour.PARTIAL);
		old.migrateLegacySplits();
		assertEquals(Armour.BURGER, old.getArmourAtEnter());
	}

	@Test
	public void weaponlessEnterIsNotARealEnter()
	{
		tick(true, false);
		ticks(10);
		tick(true, true); // ran straight into the boss room
		tracker.onLocalPlayerDeath();
		Run thrown = tick(false, false);
		assertTrue(thrown.isWeaponlessEnter());
		assertFalse(thrown.isReset());

		tick(true, false);
		ticks(10);
		tracker.onItems(Collections.singletonList("Corrupted staff (basic)"));
		tick(true, true);
		Run real = tracker.getCurrent();
		assertFalse(real.isWeaponlessEnter());

		Run reset = new Run(); // never entered: not a weaponless enter
		assertFalse(reset.isWeaponlessEnter());
	}

	@Test
	public void hunllefFightSplitsIntoIndependentQuarters()
	{
		// Your 5:19.8 run from the log
		Run run = new Run();
		run.getSplits().put(Milestone.BOSS_ROOM, 259);
		run.getSplits().put(Milestone.HUNLLEF_75, 327);
		run.getSplits().put(Milestone.HUNLLEF_50, 416);
		run.getSplits().put(Milestone.HUNLLEF_25, 480);
		run.getSplits().put(Milestone.HUNLLEF, 533);

		assertEquals(Integer.valueOf(274), run.splitTime(Milestone.HUNLLEF_FIGHT)); // 2:44.4
		assertEquals(Integer.valueOf(68), run.splitTime(Milestone.QUARTER_1));      // 40.8
		assertEquals(Integer.valueOf(89), run.splitTime(Milestone.QUARTER_2));      // 53.4
		assertEquals(Integer.valueOf(64), run.splitTime(Milestone.QUARTER_3));      // 38.4
		assertEquals(Integer.valueOf(53), run.splitTime(Milestone.QUARTER_4));      // 31.8
		assertEquals(Integer.valueOf(533), run.splitTime(Milestone.HUNLLEF));       // total, from run start

		// Quarters add up to the whole fight
		int sum = run.splitTime(Milestone.QUARTER_1) + run.splitTime(Milestone.QUARTER_2)
			+ run.splitTime(Milestone.QUARTER_3) + run.splitTime(Milestone.QUARTER_4);
		assertEquals(274, sum);

		// A run that died mid-fight has the quarters it finished, but no fight or last quarter
		Run died = new Run();
		died.getSplits().put(Milestone.BOSS_ROOM, 259);
		died.getSplits().put(Milestone.HUNLLEF_75, 327);
		assertEquals(Integer.valueOf(68), died.splitTime(Milestone.QUARTER_1));
		assertNull(died.splitTime(Milestone.QUARTER_2));
		assertNull(died.splitTime(Milestone.HUNLLEF_FIGHT));
	}

	@Test
	public void oldRunFilesFoldDemisIntoOneSplit()
	{
		Run old = new Run();
		old.getSplits().put(Milestone.BEAR, 100);
		old.getSplits().put(Milestone.DARK_BEAST, 250);
		old.getSplits().put(Milestone.DRAGON, 180);
		old.getSplits().put(Milestone.BOSS_ROOM, 300);
		old.migrateLegacySplits();
		assertEquals(Integer.valueOf(100), old.getSplits().get(Milestone.DEMIS)); // first demi
		assertFalse(old.hasSplit(Milestone.BEAR));
		assertEquals(2, old.getSplits().size());

		// A single demi kill still gives a Demi split
		Run one = new Run();
		one.getSplits().put(Milestone.DRAGON, 180);
		one.migrateLegacySplits();
		assertEquals(Integer.valueOf(180), one.getSplits().get(Milestone.DEMIS));
		assertEquals(1, one.getSplits().size());
	}
}

package com.cgsplits;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SessionTrackerTest
{
	private static final long MIN = 60_000L;

	@Test
	public void entersPerHourAverageEnterAndResets()
	{
		SessionTracker session = new SessionTracker();
		long t0 = 1_000_000L;

		session.onRunStarted(t0);
		session.onEnter(500, Armour.FULL);

		session.onRunStarted(t0 + 8 * MIN);
		session.onRunEnded(true, false); // reset in prep

		session.onRunStarted(t0 + 10 * MIN);
		session.onEnter(600, Armour.NONE);

		session.onRunStarted(t0 + 20 * MIN);
		session.onEnter(700, Armour.FULL);

		// Never left the instance, so all 30 minutes count
		SessionTracker.Snapshot s = session.snapshot(t0 + 30 * MIN);
		assertEquals(4, s.getRuns());
		assertEquals(1, s.getResets());
		assertEquals(3, s.getEnters());
		assertEquals(600, s.getAverageEnterTicks());
		assertEquals(6.0, s.getEntersPerHour(), 0.0001);
		assertEquals(30 * MIN, s.getElapsedMs());

		assertEquals(2, s.getByArmour().get(Armour.FULL).getCount());
		assertEquals(600, s.getByArmour().get(Armour.FULL).getAverageTicks());
		assertEquals(1, s.getByArmour().get(Armour.NONE).getCount());
		assertNull(s.getByArmour().get(Armour.PARTIAL));
	}

	@Test
	public void deletedRunTakenBackOut()
	{
		SessionTracker session = new SessionTracker();
		long t0 = 1_000_000L;

		session.onRunStarted(t0);
		session.onEnter(500, Armour.FULL);
		session.onRunEnded(false, true); // a real kill

		session.onRunStarted(t0 + 10 * MIN);
		session.onEnter(300, Armour.FULL);
		session.onRunEnded(false, true); // a test kill

		session.onRunStarted(t0 + 20 * MIN);
		session.onRunEnded(true, false); // a reset

		Run test = new Run();
		test.setStartedAt(t0 + 10 * MIN);
		test.getSplits().put(Milestone.BOSS_ROOM, 300);
		session.removeRun(test);

		SessionTracker.Snapshot s = session.snapshot(t0 + 30 * MIN);
		assertEquals(2, s.getRuns());
		assertEquals(1, s.getEnters());
		assertEquals(500, s.getAverageEnterTicks());
		assertEquals(1, s.getKills());
		assertEquals(1, s.getResets());
		assertEquals(1, s.getByArmour().get(Armour.FULL).getCount());
		assertEquals(500, s.getByArmour().get(Armour.FULL).getAverageTicks());
		assertEquals(1, session.overall(t0 + 30 * MIN).getEnters());

		// A run from before play time was tracked was never in the overall enters
		Run ancient = new Run();
		ancient.setStartedAt(t0 - 60 * MIN);
		ancient.getSplits().put(Milestone.BOSS_ROOM, 400);
		session.removeRun(ancient);
		assertEquals(1, session.snapshot(t0 + 30 * MIN).getEnters());
		assertEquals(1, session.overall(t0 + 30 * MIN).getEnters());

		// After a session reset, deleting an earlier run only takes it out of the overall enters
		session.reset(t0 + 30 * MIN);
		Run earlier = new Run();
		earlier.setStartedAt(t0);
		earlier.getSplits().put(Milestone.BOSS_ROOM, 500);
		session.removeRun(earlier);
		assertEquals(0, session.overall(t0 + 30 * MIN).getEnters());
		assertFalse(session.snapshot(t0 + 30 * MIN).isActive());
	}

	private static final long TICK = 600L;

	@Test
	public void shortTripsOutsideKeepCounting()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.onTick(true, 10 * MIN);

		// Reset: a few ticks in the lobby before the next run, the clock keeps going
		for (int i = 1; i <= SessionTracker.PAUSE_AFTER_TICKS_OUTSIDE; i++)
		{
			session.onTick(false, 10 * MIN + i * TICK);
		}
		// All 10 ticks outside still count
		assertEquals(10, SessionTracker.PAUSE_AFTER_TICKS_OUTSIDE);
		long last = 10 * MIN + SessionTracker.PAUSE_AFTER_TICKS_OUTSIDE * TICK;
		SessionTracker.Snapshot s = session.snapshot(last);
		assertFalse(s.isPaused());
		assertEquals(last, s.getElapsedMs());
	}

	@Test
	public void clockPausesAfterTenTicksOutside()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.onEnter(500, Armour.FULL);
		session.onTick(true, 10 * MIN);

		// The 11th tick outside pauses it, counting the time up to then
		long t = 10 * MIN;
		for (int i = 1; i <= SessionTracker.PAUSE_AFTER_TICKS_OUTSIDE + 1; i++)
		{
			t = 10 * MIN + i * TICK;
			session.onTick(false, t);
		}
		long pausedAt = t;
		assertTrue(session.snapshot(pausedAt).isPaused());

		// AFK for an hour: the clock doesn't move
		assertEquals(pausedAt, session.snapshot(pausedAt + 60 * MIN).getElapsedMs());

		// Next run resumes it
		session.onRunStarted(pausedAt + 60 * MIN);
		assertFalse(session.snapshot(pausedAt + 60 * MIN).isPaused());
		assertEquals(pausedAt + MIN, session.snapshot(pausedAt + 61 * MIN).getElapsedMs());
	}

	@Test
	public void logoutPausesStraightAway()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.pause(5 * MIN);
		assertTrue(session.snapshot(30 * MIN).isPaused());
		assertEquals(5 * MIN, session.snapshot(30 * MIN).getElapsedMs());
	}

	@Test
	public void clockDoesNotStartBeforeFirstRun()
	{
		SessionTracker session = new SessionTracker();
		session.onTick(true, 0);
		assertFalse(session.snapshot(10 * MIN).isActive());
	}

	@Test
	public void armourEnterCounts()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.onEnter(500, Armour.FULL);
		session.onEnter(400, Armour.NONE);
		session.onEnter(450, Armour.NONE);
		SessionTracker.Snapshot s = session.snapshot(MIN);
		assertEquals(1, s.entersWith(Armour.FULL));
		assertEquals(2, s.entersWith(Armour.NONE));
		assertEquals(0, s.entersWith(Armour.BURGER));
	}

	@Test
	public void resetClearsSession()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.onEnter(500, Armour.FULL);
		session.onRunEnded(true, false);
		session.onRunEnded(false, true);
		assertEquals(1, session.snapshot(MIN).getKills());
		session.reset(MIN);
		assertFalse(session.snapshot(2 * MIN).isActive());
		session.onEnter(500, Armour.FULL); // enter without a run start is ignored
		assertEquals(0, session.snapshot(3 * MIN).getEnters());
		assertEquals(0, session.snapshot(3 * MIN).getResets());
		assertEquals(0, session.snapshot(3 * MIN).getKills());
	}

	@Test
	public void overallKeepsCountingThroughSessionResets()
	{
		SessionTracker session = new SessionTracker();
		session.setOverall(new PlayTime(60 * MIN, 5, 123L)); // saved last time

		session.onRunStarted(0);
		session.onEnter(500, Armour.FULL);
		session.reset(10 * MIN);

		session.onRunStarted(20 * MIN);
		session.onEnter(450, Armour.NONE);

		// 60 saved + 10 before the reset + 5 running now; AFK time between doesn't count
		PlayTime overall = session.overall(25 * MIN);
		assertEquals(75 * MIN, overall.getMs());
		assertEquals(7, overall.getEnters());
		assertEquals(123L, overall.getSince());
	}

	@Test
	public void overallStartsAtFirstRun()
	{
		SessionTracker session = new SessionTracker();
		assertEquals(0, session.overall(MIN).getSince());
		session.onRunStarted(5 * MIN);
		assertEquals(5 * MIN, session.overall(6 * MIN).getSince());
		assertEquals(MIN, session.overall(6 * MIN).getMs());
	}

	@Test
	public void olderSavedPlayTimeDoesNotOverwriteMemory()
	{
		SessionTracker session = new SessionTracker();
		session.onRunStarted(0);
		session.pause(30 * MIN);
		session.setOverall(new PlayTime(10 * MIN, 0, 1L));
		assertEquals(30 * MIN, session.overall(40 * MIN).getMs());
	}

	@Test
	public void parsesTypedTimesAndWorldRecord()
	{
		assertEquals(Integer.valueOf(170), TimeFormat.parseUserTime("1:42"));   // 102s
		assertEquals(Integer.valueOf(171), TimeFormat.parseUserTime(" 1:42.6 "));
		assertEquals(Integer.valueOf(97), TimeFormat.parseUserTime("58"));      // plain seconds
		assertNull(TimeFormat.parseUserTime(""));
		assertNull(TimeFormat.parseUserTime("fast"));

		assertEquals(Integer.valueOf(170), WorldRecord.ticks(Milestone.BOSS_ROOM)); // 1:42
		assertEquals(Integer.valueOf(395), WorldRecord.ticks(Milestone.HUNLLEF));   // 3:57
		// The WR's prep plus its fight time is its overall time
		assertEquals(WorldRecord.ticks(Milestone.HUNLLEF),
			Integer.valueOf(WorldRecord.ticks(Milestone.BOSS_ROOM) + WorldRecord.ticks(Milestone.HUNLLEF_FIGHT)));
		assertNull(WorldRecord.ticks(Milestone.DEMIS));
	}

	@Test
	public void ephDropsDecimalsWithoutRounding()
	{
		assertEquals("4", TimeFormat.eph(4.99));
		assertEquals("4", TimeFormat.eph(4.4));
		assertEquals("5", TimeFormat.eph(5.0));
		assertEquals("0", TimeFormat.eph(0.7));
		assertEquals("4.5", TimeFormat.ephPrecise(4.567));
		assertEquals("5.0", TimeFormat.ephPrecise(5.0));
		assertEquals("0.9", TimeFormat.ephPrecise(0.999));
	}
}
